settings.custom_liquid:
{%- assign p = all_products['bandwork-4-week-band-program'] -%}
{%- assign v = p.selected_or_first_available_variant -%}
{%- capture buy_url -%}{{ routes.root_url | append: '/' | replace: '//', '/' }}cart/{{ v.id }}:1{%- endcapture -%}
<style>
  .bw{--ink:#111315;--bone:#F3F0EA;--accent:#E8572A;--muted:#5d6168;--line:#e2ddd3;color:var(--ink);font-family:var(--font-body--family),system-ui,sans-serif}
  .bw *{box-sizing:border-box}
  .bw a{color:inherit}
  .bw-wrap{max-width:1120px;margin:0 auto;padding:0 20px}
  .bw-eyebrow{font-size:12px;letter-spacing:.14em;text-transform:uppercase;font-weight:600;color:var(--accent);margin:0 0 14px}
  .bw h1,.bw h2,.bw h3{font-family:var(--font-heading--family),system-ui,sans-serif;margin:0;line-height:1.05;letter-spacing:-.01em}
  .bw-btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;min-height:52px;padding:0 26px;border-radius:999px;font-weight:600;font-size:16px;text-decoration:none;transition:transform .15s ease,opacity .15s ease}
  .bw-btn:hover{transform:translateY(-1px)}
  .bw-btn--main{background:var(--accent);color:#fff!important}
  .bw-btn--ghost{border:1px solid currentColor;color:inherit}
  .bw-hero{background:var(--ink);color:var(--bone)}
  .bw-hero .bw-wrap{display:grid;grid-template-columns:minmax(0,1.05fr) minmax(0,1fr);gap:48px;align-items:center;padding-top:72px;padding-bottom:72px}
  .bw-hero h1{font-size:clamp(40px,6vw,72px);text-transform:none}
  .bw-hero h1 span{color:var(--accent)}
  .bw-hero p.lead{font-size:18px;line-height:1.55;color:#cfcac1;max-width:34ch;margin:20px 0 28px}
  .bw-ctas{display:flex;flex-wrap:wrap;gap:12px}
  .bw-trust{display:flex;flex-wrap:wrap;gap:8px 18px;margin-top:22px;font-size:14px;color:#cfcac1;list-style:none;padding:0}
  .bw-trust li::before{content:"✓ ";color:var(--accent);font-weight:700}
  .bw-hero img{width:100%;height:auto;display:block;border-radius:14px}
  .bw-section{padding:72px 0}
  .bw-section h2{font-size:clamp(30px,4vw,44px);margin-bottom:12px}
  .bw-section .sub{color:var(--muted);font-size:17px;line-height:1.55;max-width:56ch;margin:0 0 36px}
  .bw-cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}
  .bw-card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:26px}
  .bw-card .n{font-size:13px;font-weight:700;color:var(--accent);letter-spacing:.08em}
  .bw-card h3{font-size:21px;margin:10px 0 8px}
  .bw-card p{margin:0;color:var(--muted);line-height:1.55;font-size:15px}
  .bw-bone{background:var(--bone)}
  .bw-inside{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:48px;align-items:center}
  .bw-pages{display:grid;grid-template-columns:1fr 1fr;gap:14px}
  .bw-pages img{width:100%;height:auto;display:block;border-radius:8px;box-shadow:0 18px 40px rgba(17,19,21,.16);background:#fff}
  .bw-list{list-style:none;padding:0;margin:0 0 26px;counter-reset:bw}
  .bw-list li{counter-increment:bw;display:grid;grid-template-columns:34px minmax(0,1fr);gap:12px;padding:14px 0;border-bottom:1px solid var(--line);font-size:16px;line-height:1.5}
  .bw-list li::before{content:counter(bw);display:grid;place-items:center;width:28px;height:28px;border-radius:50%;background:var(--ink);color:var(--bone);font-size:13px;font-weight:700}
  .bw-list b{display:block}
  .bw-need{margin:0 0 26px;color:var(--muted);font-size:15px;line-height:1.55}
  .bw-coach{background:var(--ink);color:var(--bone)}
  .bw-coach .bw-wrap{max-width:820px;text-align:center}
  .bw-coach blockquote{margin:0;font-family:var(--font-heading--family),system-ui,sans-serif;font-size:clamp(22px,3vw,30px);line-height:1.35}
  .bw-coach .who{margin-top:22px;color:#cfcac1;font-size:15px;line-height:1.6}
  .bw-coach .who b{color:var(--bone)}
  .bw-faq{max-width:760px}
  .bw-faq details{border-bottom:1px solid var(--line);padding:18px 0}
  .bw-faq summary{cursor:pointer;font-weight:600;font-size:17px;list-style:none;display:flex;justify-content:space-between;gap:16px}
  .bw-faq summary::-webkit-details-marker{display:none}
  .bw-faq summary::after{content:"+";color:var(--accent);font-size:22px;line-height:1}
  .bw-faq details[open] summary::after{content:"–"}
  .bw-faq p{margin:10px 0 0;color:var(--muted);line-height:1.6}
  .bw-final{text-align:center}
  .bw-final .price{font-size:15px;color:var(--muted);margin:14px 0 0}
  .bw-fine{font-size:13px;color:var(--muted);text-align:center;padding:0 20px 40px;margin:0}
  @media (max-width:849px){
    .bw-hero .bw-wrap,.bw-inside{grid-template-columns:minmax(0,1fr);gap:32px}
    .bw-hero .bw-wrap{padding-top:44px;padding-bottom:52px}
    .bw-cards{grid-template-columns:minmax(0,1fr)}
    .bw-section{padding:52px 0}
    .bw-btn{width:100%}
  }
</style>

<div class="bw">
  <section class="bw-hero">
    <div class="bw-wrap">
      <div>
        <p class="bw-eyebrow">Bandwork · home strength programs</p>
        <h1>Home strength, <span>coached.</span></h1>
        <p class="lead">A real 4-week plan for a resistance band and a door. Three 30-minute sessions a week, written by a certified strength coach.</p>
        <div class="bw-ctas">
          <a class="bw-btn bw-btn--main" href="{{ buy_url }}">Get the program · {{ v.price | money_with_currency }}</a>
          <a class="bw-btn bw-btn--ghost" href="#bw-inside">See what's inside</a>
        </div>
        <ul class="bw-trust">
          <li>Instant PDF download</li>
          <li>30-day money-back guarantee</li>
        </ul>
      </div>
      <div>
        {%- if p.featured_image -%}
          {{ p.featured_image | image_url: width: 1400 | image_tag: loading: 'eager', fetchpriority: 'high', alt: 'The Bandwork 4-Week Band Strength Program, cover and pages', sizes: '(min-width: 850px) 50vw, 100vw' }}
        {%- endif -%}
      </div>
    </div>
  </section>

  <section class="bw-section bw-bone">
    <div class="bw-wrap">
      <p class="bw-eyebrow">How it works</p>
      <h2>A plan, not a playlist.</h2>
      <p class="sub">Most band workouts are a random list of exercises. Bandwork tells you what to do each day, how hard, and how to make it harder.</p>
      <div class="bw-cards">
        <div class="bw-card"><div class="n">01</div><h3>Learn the moves</h3><p>Weeks 1-2 teach the squat, hinge, press, pull and core patterns with a light band.</p></div>
        <div class="bw-card"><div class="n">02</div><h3>Add load</h3><p>Weeks 3-4 add sets and tension, so you keep getting stronger instead of just tired.</p></div>
        <div class="bw-card"><div class="n">03</div><h3>Track it</h3><p>Test two lifts on day 1 and again in week 4, and write down the band and reps each week.</p></div>
      </div>
    </div>
  </section>

  <section class="bw-section" id="bw-inside">
    <div class="bw-wrap bw-inside">
      <div class="bw-pages">
        {%- if p.images[1] -%}{{ p.images[1] | image_url: width: 800 | image_tag: loading: 'lazy', alt: 'Coaching cues page' }}{%- endif -%}
        {%- if p.images[2] -%}{{ p.images[2] | image_url: width: 800 | image_tag: loading: 'lazy', alt: 'Progress log page' }}{%- endif -%}
      </div>
      <div>
        <p class="bw-eyebrow">What's inside</p>
        <h2>6 pages. Everything you need, nothing you don't.</h2>
        <ol class="bw-list">
          <li><span><b>How to use it, plus a safety check</b>for your band, handles and door before every session.</span></li>
          <li><span><b>Weeks 1-2: learn the patterns</b>Two full-body sessions, A and B, each with a 5-minute warm-up.</span></li>
          <li><span><b>Weeks 3-4: build strength</b>Move up a band, add sets, and finish with a 3-round finisher.</span></li>
          <li><span><b>Coaching cues for every exercise</b>How to set up and how to move, in plain words.</span></li>
          <li><span><b>Your progress log</b>A day 1 test and a week 4 retest, so you can see the change.</span></li>
        </ol>
        <p class="bw-need"><b>What you need:</b> a tube-band set with handles, a door anchor and ankle straps, a door that closes, and about 2 metres of floor. US Letter PDF: prints well and reads well on a phone.</p>
        <a class="bw-btn bw-btn--main" href="{{ buy_url }}">Get the program · {{ v.price | money_with_currency }}</a>
      </div>
    </div>
  </section>

  <section class="bw-section bw-coach">
    <div class="bw-wrap">
      <p class="bw-eyebrow">From the coach</p>
      <blockquote>“I've coached people on gym floors who wanted to train but couldn't make the gym fit their week. Bands fix the where. A real plan fixes the what.”</blockquote>
      <p class="who"><b>Hussein Dar Abu Hussein</b><br>ISSA Certified Personal Trainer · ISSA Strength &amp; Conditioning Specialist · Ottawa, Canada</p>
    </div>
  </section>

  <section class="bw-section bw-bone">
    <div class="bw-wrap bw-faq">
      <p class="bw-eyebrow">Questions</p>
      <h2>Before you start</h2>
      <details open><summary>What bands do I need?</summary><p>Any tube-band set with handles, a door anchor and ankle straps. If you can attach a band to a door and hold both handles, you're set.</p></details>
      <details><summary>I'm a complete beginner. Is it OK?</summary><p>Yes. Weeks 1-2 are built to teach the movements with a light band before anything gets harder.</p></details>
      <details><summary>How do I get the program?</summary><p>You download it right after checkout, and a copy goes to your email.</p></details>
      <details><summary>What if it's not for me?</summary><p>Email {{ shop.email }} within 30 days of purchase for a full refund. No forms.</p></details>
      <details><summary>Is this medical advice?</summary><p>No. It's general fitness guidance. If you have a medical condition or an injury, check with your doctor before starting.</p></details>
    </div>
  </section>

  <section class="bw-section bw-final">
    <div class="bw-wrap">
      <h2>Start your 4 weeks today.</h2>
      <p class="sub" style="margin:12px auto 26px">Three sessions a week, 30 minutes each, one band and a door.</p>
      <a class="bw-btn bw-btn--main" href="{{ buy_url }}">Get the program · {{ v.price | money_with_currency }}</a>
      <p class="price">Instant download · 30-day money-back guarantee</p>
    </div>
  </section>
  <p class="bw-fine">General fitness guidance, not medical advice.</p>
</div>
